"""KinDER i00. Sensors-only control; action history is saved for replay.
Run `python gen.py replay` to send the recorded actions in a fresh service.
"""
import json, pathlib, sys, math, argparse
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=pathlib.Path('/app/output'); OUT.mkdir(exist_ok=True)
r=Robot(); spec=r.spec()
J=np.array(spec['arm']['position_m']); AX=np.array(spec['arm']['axis'])
EE=np.array(spec['arm']['end_effector']['position_m'])
def fk(q,point=EE):
    R=np.eye(3); t=np.zeros(3)
    for a,p,angle in zip(AX,J,q):
        Ri=Rotation.from_rotvec(a*angle).as_matrix()
        t=t+R@(p-Ri@p); R=R@Ri
    return R@point+t,R

def now():
    return np.array(r.get_obs(cameras=[],video='none').meta['proprio']['now'])
def world_pose(s,point=EE):
    p,R=fk(s[6:13],point); B=Rotation.from_euler('z',s[2]).as_matrix()
    return B@p+np.r_[s[:2],0],B@R

def obs(tag='obs'):
    res=r.get_obs(include_depth=True,video='none'); res.save(str(OUT/tag))
    np.savez(OUT/(tag+'.npz'),**res.last,depth=res.depth['robot_wrist'][-1],state=res.meta['proprio']['now'])
    print(json.dumps(res.meta)); return res

def send(A,tag=None):
    A=np.asarray(A,dtype=float).reshape(-1,11)
    with (OUT/'actions.jsonl').open('a') as f: f.write(json.dumps(A.tolist())+'\n')
    res=r.submit('delta',A,cameras=['robot_wrist'],video='none',include_depth=True)
    if tag:
        res.save(str(OUT/tag))
        np.savez(OUT/(tag+'.npz'),**res.last,depth=res.depth['robot_wrist'][-1],state=res.meta['proprio']['now'])
    if res.done: print('EPISODE',json.dumps(res.meta)); sys.exit(0)
    return np.array(res.meta['proprio']['now'])

def move(q=None,base=None,grip=0,rate=.075,tol=.008,max_steps=100,tag='move'):
    s=now(); qt=s[6:13] if q is None else np.array(q); bt=s[:3] if base is None else np.array(base)
    for i in range(max_steps):
        dq=qt-s[6:13]; db=bt-s[:3]
        if np.max(np.abs(dq))<tol and np.max(np.abs(db))<.003: break
        a=np.zeros(11); a[:3]=np.clip(db,-rate,rate)
        norm=np.linalg.norm(a[:2]);
        if norm>.09: a[:2]*=.09/norm
        a[3:10]=np.clip(dq,-rate,rate); a[10]=grip
        s=send([a])
    print('move',i,'state',s[:13].tolist(),'ee',world_pose(s)[0].tolist(),'error',np.max(abs(qt-s[6:13])))
    obs(tag); return s

def ik(p,R=None,q0=None,base=None):
    s=now(); b=s[:3] if base is None else np.array(base); B=Rotation.from_euler('z',b[2]).as_matrix()
    target=B.T@(np.array(p)-np.r_[b[:2],0]); Rt=None if R is None else B.T@np.array(R)
    q0=s[6:13] if q0 is None else np.array(q0)
    low=np.array([-20,-2.239,-20,-2.569,-20,-2.089,-20]); hi=-low
    def fun(q):
        pos,rot=fk(q); out=list((pos-target)*6)
        if Rt is not None: out.extend(Rotation.from_matrix(Rt@rot.T).as_rotvec()*1.2)
        out.extend((q-q0)*.012)
        return out
    sol=least_squares(fun,np.clip(q0,low+.001,hi-.001),bounds=(low,hi),max_nfev=500)
    print('ik',sol.x.tolist(),'pos',fk(sol.x)[0].tolist(),'err',np.linalg.norm(fun(sol.x)[:3])/6)
    return sol.x

def camera(s,name='robot_wrist'):
    c=spec['cameras'][name]; cp=c['pose']; pos=np.array(cp['position_m']);
    right=np.array(cp['right']); up=np.array(cp['up']); fw=np.array(cp['forward'])
    B=Rotation.from_euler('z',s[2]).as_matrix()
    if name=='robot_wrist': pos,R=fk(s[6:13],pos)
    else: R=np.eye(3)
    return B@pos+np.r_[s[:2],0],B@R@np.column_stack([right,-up,fw])

def points(data,name='robot_wrist',plane_z=.012):
    s=data['state']; cp,C=camera(s,name); H,W=data[name].shape[:2]; f=H/(2*np.tan(np.radians(spec['cameras'][name]['fovy_deg'])/2))
    u,v=np.meshgrid(np.arange(W),np.arange(H)); rays=np.stack([(u-(W-1)/2)/f,(v-(H-1)/2)/f,np.ones_like(u)],-1)@C.T
    if name=='robot_wrist': d=data['depth']; P=cp+rays*d[:,:,None]
    else: d=(plane_z-cp[2])/rays[:,:,2]; P=cp+rays*d[:,:,None]
    return P

if __name__=='__main__':
    ap=argparse.ArgumentParser(); ap.add_argument('cmd',nargs='?',default='observe');ap.add_argument('--tag',default='obs');ap.add_argument('--q');ap.add_argument('--base');ap.add_argument('--p');ap.add_argument('--rot');ap.add_argument('--grip',type=float,default=0);ap.add_argument('--steps',type=int,default=0)
    a=ap.parse_args(); parse=lambda v: None if v is None else np.array(json.loads(v))
    if a.cmd=='observe':obs(a.tag)
    elif a.cmd=='move':
        q=parse(a.q)
        if a.p: q=ik(parse(a.p),parse(a.rot),base=parse(a.base))
        move(q,parse(a.base),a.grip,tag=a.tag)
    elif a.cmd=='hold': send(np.tile(np.r_[np.zeros(10),a.grip],(a.steps,1)),a.tag);obs(a.tag)
    elif a.cmd=='replay':
        for line in (OUT/'actions.jsonl').read_text().splitlines():
            res=r.submit('delta',json.loads(line),cameras=[],video='none')
            if res.done: print(res.meta);break
PY
